manifest:
{
  "manifest_version": 3,
  "name": "__MSG_extName__",
  "short_name": "__MSG_extShortName__",
  "version": "1.1.7",
  "default_locale": "zh_CN",
  "description": "__MSG_extDescription__",
  "icons": {
    "16": "icons/icon16.png",
    "32": "icons/icon32.png",
    "48": "icons/icon48.png",
    "128": "icons/icon128.png"
  },
  "action": {
    "default_title": "__MSG_extTitle__",
    "default_icon": {
      "16": "icons/icon16.png",
      "32": "icons/icon32.png",
      "48": "icons/icon48.png",
      "128": "icons/icon128.png"
    }
  },
  "background": {
    "service_worker": "src/background/service-worker.js"
  },
  "content_scripts": [
    {
      "matches": [
        "<all_urls>"
      ],
      "js": [
        "src/shared/defaults.js",
        "src/content/json-parser.js",
        "src/content/rowmodel.js",
        "src/content/viewer.js",
        "src/content/content.js"
      ],
      "run_at": "document_end",
      "all_frames": false,
      "match_about_blank": false
    }
  ],
  "permissions": [
    "storage",
    "contextMenus",
    "activeTab"
  ],
  "host_permissions": [
    "<all_urls>"
  ],
  "options_ui": {
    "page": "src/options/options.html",
    "open_in_tab": true
  },
  "commands": {
    "toggle-format": {
      "suggested_key": {
        "default": "Alt+Shift+J"
      },
      "description": "格式化 / 还原当前页面 JSON"
    }
  },
  "minimum_chrome_version": "102",
  "update_url": "https://edge.microsoft.com/extensionwebstorebase/v1/crx"
}
